#!/usr/bin/env python3
"""Merge the three user sources using source priority."""
from __future__ import annotations

import argparse
import json
from datetime import date, datetime
from pathlib import Path
from typing import Any

import pandas as pd

SOURCE_ORDER = ("source_a", "source_b", "source_c")
FIELD_ALIASES = {
    "user_id": ("user_id", "id", "userId"),
    "email": ("email", "email_address"),
    "name": ("full_name", "name", "userName"),
    "created_date": ("registration_date", "created_at", "joined"),
    # These aliases are useful for the optional output column.
    "status": ("status", "is_active", "active"),
}
OUTPUT_FIELDS = ("name", "email", "created_date", "status")


def read_source(path: Path) -> list[dict[str, Any]]:
    if path.suffix.lower() == ".json":
        with path.open(encoding="utf-8") as handle:
            data = json.load(handle)
        if isinstance(data, dict):
            data = data.get("users", data)
        if not isinstance(data, list):
            raise ValueError(f"JSON source must contain a list of users: {path}")
        return [dict(row) for row in data]
    if path.suffix.lower() == ".csv":
        return pd.read_csv(path, dtype=object, keep_default_na=False).to_dict("records")
    if path.suffix.lower() == ".parquet":
        return pd.read_parquet(path).to_dict("records")
    raise ValueError(f"Unsupported source format: {path}")


def is_missing(value: Any) -> bool:
    if value is None:
        return True
    try:
        return bool(pd.isna(value))
    except (TypeError, ValueError):
        return False


def clean_value(field: str, value: Any) -> Any:
    if is_missing(value) or (isinstance(value, str) and not value.strip()):
        return None
    if field == "user_id":
        try:
            number = int(value)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Invalid user_id: {value!r}") from exc
        if isinstance(value, float) and value != number:
            raise ValueError(f"user_id must be an integer: {value!r}")
        return number
    if field == "created_date":
        parsed = pd.to_datetime(value, errors="raise")
        return parsed.strftime("%Y-%m-%d")
    if field == "status":
        if isinstance(value, bool):
            return "active" if value else "inactive"
        text = str(value).strip()
        if text.lower() in {"true", "yes", "1", "active"}:
            return "active"
        if text.lower() in {"false", "no", "0", "inactive"}:
            return "inactive"
        return text
    return str(value).strip() if isinstance(value, str) else value


def canonical_record(raw: dict[str, Any]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for field, aliases in FIELD_ALIASES.items():
        for alias in aliases:
            if alias in raw and not is_missing(raw[alias]) and raw[alias] != "":
                result[field] = clean_value(field, raw[alias])
                break
    if "user_id" not in result:
        raise ValueError(f"Record has no user_id: {raw!r}")
    return result


def merge(sources: dict[str, list[dict[str, Any]]]) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    by_user: dict[int, dict[str, dict[str, Any]]] = {}
    for source in SOURCE_ORDER:
        for raw in sources[source]:
            record = canonical_record(raw)
            uid = record["user_id"]
            # Merge duplicate rows in one source without allowing a later row
            # to erase a populated value.
            existing = by_user.setdefault(uid, {}).setdefault(source, {})
            for field, value in record.items():
                if field not in existing or existing[field] is None:
                    existing[field] = value

    conflicts: list[dict[str, Any]] = []
    merged: list[dict[str, Any]] = []
    for uid in sorted(by_user):
        records = by_user[uid]
        output: dict[str, Any] = {"user_id": uid}
        for field in OUTPUT_FIELDS:
            values = {source: records[source][field] for source in SOURCE_ORDER
                      if source in records and field in records[source] and records[source][field] is not None}
            if values:
                selected = next(values[source] for source in SOURCE_ORDER if source in values)
                output[field] = selected
                distinct = {json.dumps(value, sort_keys=True, default=str) for value in values.values()}
                if len(distinct) > 1:
                    conflicts.append({
                        "user_id": uid,
                        "field": field,
                        "values": {source: values[source] for source in SOURCE_ORDER if source in values},
                        "selected": selected,
                    })
        merged.append(output)
    return merged, {"total_conflicts": len(conflicts), "conflicts": conflicts}


def write_outputs(rows: list[dict[str, Any]], report: dict[str, Any], parquet_path: Path, report_path: Path) -> None:
    columns = ["user_id", "name", "email", "created_date"]
    if any("status" in row for row in rows):
        columns.append("status")
    frame = pd.DataFrame(rows, columns=columns)
    frame["user_id"] = frame["user_id"].astype("int64")
    for column in columns:
        if column != "user_id":
            frame[column] = frame[column].astype("string")
    parquet_path.parent.mkdir(parents=True, exist_ok=True)
    report_path.parent.mkdir(parents=True, exist_ok=True)
    frame.to_parquet(parquet_path, index=False)
    with report_path.open("w", encoding="utf-8") as handle:
        json.dump(report, handle, indent=2, ensure_ascii=False)
        handle.write("\n")


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--source-a", default="/data/source_a/users.json")
    parser.add_argument("--source-b", default="/data/source_b/users.csv")
    parser.add_argument("--source-c", default="/data/source_c/users.parquet")
    parser.add_argument("--output", default="/app/merged_users.parquet")
    parser.add_argument("--conflicts", default="/app/conflicts.json")
    args = parser.parse_args()
    sources = {name: read_source(Path(path)) for name, path in {
        "source_a": args.source_a, "source_b": args.source_b, "source_c": args.source_c
    }.items()}
    rows, report = merge(sources)
    write_outputs(rows, report, Path(args.output), Path(args.conflicts))
    print(f"Merged {len(rows)} users; found {report['total_conflicts']} conflicts")


if __name__ == "__main__":
    main()
